function finishGame(s){if(s.phase!=='play')return;const g=s.game,teamGame=catalog.find(d=>d.id===g.id)?.format==='teams';const scores=s.players.map(p=>({id:p.id,name:p.name,score:Math.round(teamGame?(Number.isInteger(g.winnerTeam)?p.team===g.winnerTeam?3000:1000:g.teamScores[p.team]*(g.id==='football'?1000:1)):p.score),team:p.team})).sort((a,b)=>b.score-a.score||a.id.localeCompare(b.id));const reward=[12,9,7,5,4,3,2,1];let lastScore=null,lastPlace=0;s.results=scores.map((r,i)=>{const place=r.score===lastScore?lastPlace:i+1;lastScore=r.score;lastPlace=place;const p=s.players.find(p=>p.id===r.id),gain=reward[place-1]||1;coins(s,p,gain);p.totalScore+=r.score;if(place===1){p.wins++;if(s.mode!=='board')p.stars++;}p.ready=false;return{...r,place,coins:gain,stars:place===1&&s.mode!=='board'?1:0};});s.phase='results';s.phaseTime=0;note(s,(s.results[0]?.name||'A turma')+' venceu '+g.name+'! Moedas distribuídas.');}
